A="ditto:$DITTO_PASSWORD"
snap(){ python3 - "$A" <<'PY'
import json,sys,urllib.request,base64
a=base64.b64encode(sys.argv[1].encode()).decode()
def g(u,auth=True):
  r=urllib.request.Request(u,headers={'Authorization':'Basic '+a} if auth else {});return json.load(urllib.request.urlopen(r))
ad=g('http://127.0.0.1:8088/api/advisor',False)
f=lambda t,k:g(f'http://127.0.0.1:8080/api/2/things/kz.sekis:{t}/features/{k}/properties/value')
out={'binding':ad['binding_link'],'achievable':ad['achievable_ktpa']}
for t,k in [('mine','air_delivered_m3s'),('mine','air_demand_m3s'),('mine','units_held_vent'),('mine','fan_power_kw'),('mine','vod_state'),('mine','inflow_m3h'),('mine','flood_volume_m3'),('decline-tu1','state'),('decline-tu2','state')]:
  try: out[t+'.'+k]=f(t,k)
  except Exception as e: out[t+'.'+k]='ERR'
print(json.dumps(out,ensure_ascii=False))
PY
}
post(){ curl -s -X POST -H 'Content-Type: application/json' -d "$1" 127.0.0.1:8088/api/scenario | head -c 120; echo; }
EOF
